def feature(text: str) -> float:
    "Proportion of unique words in the text"
    words = text.split()
    unique_words = set(words)
    if len(words) == 0:
        return 0.0
    return float(len(unique_words)) / len(words)

def feature(text: str) -> float:
    "Total count of non-alphanumeric characters in the text"
    non_alpha_count = sum(1 for c in text if not c.isalnum() and not c.isspace())
    return float(non_alpha_count)

def feature(text: str) -> float:
    "Average number of characters per sentence"
    sentences = re.split(r'[.!?]+', text)
    char_count = sum(len(s) for s in sentences if s.strip())
    if len(sentences) == 0:
        return 0.0
    return char_count / len(sentences)

def feature(text: str) -> float:
    "Ratio of questions to total sentences"
    sentences = re.split(r'[.!?]+', text)
    question_count = sum(1 for s in sentences if '?' in s)
    if len(sentences) == 0:
        return 0.0
    return float(question_count) / len(sentences)

def feature(text: str) -> float:
    "Total number of numeric characters in the text"
    numeric_count = sum(c.isdigit() for c in text)
    return float(numeric_count)

def feature(text: str) -> float:
    "Average similarity of word lengths to the mean word length"
    words = text.split()
    if not words:
        return 0.0
    mean_length = sum(len(word) for word in words) / len(words)
    similarity = sum(abs(len(word) - mean_length) for word in words) / len(words)
    return float(similarity)

