    words = text.split()
    total_length = sum(len(word) for word in words)
    return float(total_length) / len(words) if words else 0.0

def feature(text: str) -> float:
    "Count of words that start with a vowel"
    vowel_count = sum(1 for word in text.split() if word[0].lower() in 'aeiou')
    return float(vowel_count)

def feature(text: str) -> float:
    "Average number of clauses per sentence"
    sentences = re.split(r'[.!?]+', text)
    clause_counts = [s.count(',') + s.count('and') + s.count('but') + 1 for s in sentences if s]
    return float(sum(clause_counts) / len(clause_counts)) if clause_counts else 0.0
def feature(text: str) -> float:
    "Count of characters in the text excluding spaces"
    return float(len(text.replace(' ', '')))

def feature(text: str) -> float:
    "Proportion of uppercase letters in the text"
    upper_count = sum(1 for c in text if c.isupper())
    return upper_count / len(text) if text else 0.0

def feature(text: str) -> float:
    "Count of distinct punctuation marks used in the text"
    unique_punctuation = set(c for c in text if not c.isalnum() and not c.isspace())
    return float(len(unique_punctuation))

def feature(text: str) -> float:
    "Average length of sentences in terms of characters"
    sentences = re.split(r'[.!?]+', text)
    lengths = [len(s.strip()) for s in sentences if s.strip()]
    return float(sum(lengths)) / len(lengths) if lengths else 0.0

def feature(text: str) -> float:
    "Count of words that exceed 10 characters"
    long_word_count = sum(1 for word in text.split() if len(word) > 10)
    return float(long_word_count)

def feature(text: str) -> float:
    "Count of words that start and end with the same letter"
    same_letter_count = sum(1 for word in text.split() if word and word[0].lower() == word[-1].lower())
    return float(same_letter_count)

def feature(text: str) -> float:
    "Average number of syllables per word"
    syllable_count = sum(sum(1 for c in word if c in 'aeiou') for word in text.split())
    word_count = len(text.split())
    return float(syllable_count) / word_count if word_count else 0.0

def feature(text: str) -> float:
    "Ratio of long sentences (more than 15 words) to total sentences"
    sentences = re.split(r'[.!?]+', text)
    long_sentence_count = sum(1 for s in sentences if len(s.split()) > 15)
    return float(long_sentence_count) / len(sentences) if sentences else 0.0

def feature(text: str) -> float:
    "Count of characters that are not letters or digits"
    non_alnum_count = sum(1 for c in text if not c.isalnum())
    return float(non_alnum_count)

def feature(text: str) -> float:
    "Proportion of negative sentiment words in text"
    negative_words = ['not', 'no', 'never', 'none', 'nothing']
    negative_count = sum(text.lower().count(word) for word in negative_words)
    total_word_count = len(text.split())
    return negative_count / total_word_count if total_word_count else 0.0
def feature(text: str) -> float:
    "Average sentence length measured in characters"
    sentences = re.split(r'[.!?]+', text)
    lengths = [len(s) for s in sentences if s.strip()]
    return float(sum(lengths) / len(lengths)) if lengths else 0.0

def feature(text: str) -> float:
    "Count of words shorter than 3 characters"
    short_word_count = sum(1 for word in text.split() if len(word) < 3)
    return float(short_word_count)

def feature(text: str) -> float:
    "Proportion of unique letters in the text"
    unique_letters = set(c.lower() for c in text if c.isalpha())
    return float(len(unique_letters)) / len(set(text.lower())) if len(text) > 0 else 0.0

def feature(text: str) -> float:
    "Count of words that are palindromes"
    palindrome_count = sum(1 for word in text.split() if word.lower() == word[::-1].lower())
    return float(palindrome_count)

def feature(text: str) -> float:
    "Duration of positive sentiment words"
    positive_words = ['good', 'great', 'excellent', 'happy', 'joy', 'love']
    count = sum(text.lower().count(word) for word in positive_words)
    return float(count)

def feature(text: str) -> float:
    "Count of words that contain numbers"
    number_word_count = sum(1 for word in text.split() if any(c.isdigit() for c in word))
    return float(number_word_count)

def feature(text: str) -> float:
    "Proportion of words with 3 or more syllables"
    three_or_more_syllable_words = sum(1 for word in text.split() if len(re.findall(r'[^aeiouy]*[aeiouy]+[^aeiouy]*', word)) >= 3)
    total_words = len(text.split())
    return float(three_or_more_syllable_words) / total_words if total_words > 0 else 0.0

def feature(text: str) -> float:
    "Count of different punctuation marks in the text"
    punctuation_count = sum(1 for c in text if c in string.punctuation)
    return float(punctuation_count)

def feature(text: str) -> float:
    "Average number of characters in words longer than 5 characters"
    long_words = [word for word in text.split() if len(word) > 5]
    return float(sum(len(word) for word in long_words) / len(long_words)) if long_words else 0.0

def feature(text: str) -> float:
    "Total count of capitalized words in the text"
    capitalized_word_count = sum(1 for word in text.split() if word[0].isupper())
    return float(capitalized_word_count)
def feature(text: str) -> float:
    "Count of non-empty lines in the text"
    return float(len([line for line in text.splitlines() if line.strip()]))

def feature(text: str) -> float:
    "Percentage of punctuation characters in the text"
    punctuation_count = sum(1 for c in text if c in string.punctuation)
    return float(punctuation_count) / len(text) if text else 0.0

def feature(text: str) -> float:
    "Count of words with a vowel count greater than 3"
    words = text.split()
    vowel_count = sum(1 for word in words if sum(1 for char in word if char.lower() in 'aeiou') > 3)
    return float(vowel_count)

def feature(text: str) -> float:
    "Average sentence length measured in characters"
    sentences = re.split(r'[.!?]+', text)
    lengths = [len(s) for s in sentences if s]
    return float(statistics.mean(lengths)) if lengths else 0.0

def feature(text: str) -> float:
    "Count of words with both uppercase and lowercase letters"
    mixed_case_count = sum(1 for word in text.split() if any(c.isupper() for c in word) and any(c.islower() for c in word))
    return float(mixed_case_count)

def feature(text: str) -> float:
    "Percentage of words that are longer than the average word length"
    words = text.split()
    avg_length = sum(len(word) for word in words) / len(words) if words else 0
    longer_words_count = sum(1 for word in words if len(word) > avg_length)
    return float(longer_words_count) / len(words) if words else 0.0

def feature(text: str) -> float:
    "Count of unique characters in the text"
    unique_char_count = len(set(text))
    return float(unique_char_count)

def feature(text: str) -> float:
    "Normalized proportion of sentences that end with a question mark"
    sentences = re.split(r'[.!?]+', text)
    question_sentences = sum(1 for s in sentences if s.endswith('?'))
    return float(question_sentences) / len(sentences) if sentences else 0.0

